for label,n,pr,v in [('menor',6,45,5),('moderada',10,180,10),('maior',14,850,15)]:item('pocao-resistencia-'+label,'Poção de resistência '+label,n,pr,260,f'Resistência {v} por 1 hora a ácido, frio, eletricidade, fogo ou sônico, escolhido na criação, não pelo usuário a cada uso. Consumida ao beber.',f'Resistência {v} a uma energia por 1 hora.',categoria='poção',uso='Uma mão; Volume leve',ativacao='Uma ação; manuseio')
